effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec2 u_xlat2;
void main()
{
    u_xlat0.x = _spread * _spread;
    u_xlat0.x = u_xlat0.x * _blend;
    u_xlat0.x = (-u_xlat0.x) * 0.5 + 1.0;
    u_xlat2.xy = acScreenNorm.xy + (-_center.xy);
    u_xlat0.xy = u_xlat2.xy * u_xlat0.xx + _center.xy;
    u_xlat1 = texture(prev_buffer, u_xlat0.xy);
    u_xlat0 = texture(inputImg, u_xlat0.xy);
    u_xlat1 = (-u_xlat0) + u_xlat1;
    fragColor = u_xlat1 * vec4(0.949999988, 0.949999988, 0.949999988, 0.949999988) + u_xlat0;
    return;
}
